INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Veyora', 'Veyora is a medieval open-world RPG with elements of farming, survival, and adventure. In a vast, stylized world, you decide where to live and what to create – whether near a bustling town, in the lonely mountains, or by a peaceful lake. Each location offers its own resources, challenges, and opportunities.' FROM games WHERE igdb_id = 386298 ON CONFLICT (game_id, language_code) DO NOTHING;
