INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love in Space', 'It is the year 2009. A short time after "the incident". Mankind has fled the scorched crusts of planet earth for a better life in space. Those unlucky few who still reside on earth are forced to live beneath the sea in leaky metal domes. This includes you... 50% Visual Novel - 50% Karaoke-Musical.' FROM games WHERE igdb_id = 309917 ON CONFLICT (game_id, language_code) DO NOTHING;
