INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vice Versa', 'Play solo or with up to 5 players in this strategic card-stacking challenge. Place your entire deck on ascending and descending stacks, use clever resets, and survive two unique modes filled with tense, cooperative decision-making.' FROM games WHERE igdb_id = 387762 ON CONFLICT (game_id, language_code) DO NOTHING;
