INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantom the Huntress', 'Not sword-clanging trash. Not glitter-magic garbage. Bow only. The rest is for peasants. I’m Phantom, elite huntress, eternally exhausted. You’ll track, gather, goblin-slay, babysit dumb NPCs and rank up at snail pace. Wishlist now. I get bonus wine money. Do it or vanish. My patience is dead.' FROM games WHERE igdb_id = 390092 ON CONFLICT (game_id, language_code) DO NOTHING;
