INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lobsterpunk', 'Lockpick your way through an abandoned city powered solely by the combustion of lobsters. Bring the dead machinery one last breath of life before their steel forms lay cold forever. As you do, see the memories of the last man on earth, and how familiar that might feel, however foreign the setting.' FROM games WHERE igdb_id = 369895 ON CONFLICT (game_id, language_code) DO NOTHING;
