INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jaden Williams'' The Stalking Stairs', 'The city’s under curfew after a series of disappearances and murders. You’re a young delivery driver trying to finish your gig before 9:00 PM. Set inside a decaying apartment complex, every knock on a door brings you closer to uncovering what lurks within its halls, where every delivery could be your last. The Stalking Stairs is a PSX-style psychological horror thriller featuring tense atmosphere, immersive sound design, and full voice acting.' FROM games WHERE igdb_id = 388627 ON CONFLICT (game_id, language_code) DO NOTHING;
