INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'School Days', '"School Days" is a highly flexible campus development game. Summer watermelons, afternoon ceiling fans, and a throbbing heart transport you back to the early 2000s. Study, exercise, and fall in love—will you retrace your past path or live a different life? 12 years from now, what will your future hold? It''s up to you to decide!' FROM games WHERE igdb_id = 371896 ON CONFLICT (game_id, language_code) DO NOTHING;
