INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hordes of Hunger', 'Hordes of Hunger is a fast-paced action arena slasher with rogue-lite elements set in the dark fantasy setting of Ismer. A land engulfed by the living hunger, the cosmic horror known only as the Beast. You are the unlucky one still living inside the nightmare and the only way out is through it.' FROM games WHERE igdb_id = 244839 ON CONFLICT (game_id, language_code) DO NOTHING;
