INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drudge', 'You are a slave. A collar with three lights hangs around your neck: each one fades and shocks you for mistakes or disobedience. Your life is quotas: sorting waste, growing food, and expeditions into lower levels with zombies. Earn, unlock passages, buy gear, and seek a path to freedom.' FROM games WHERE igdb_id = 388738 ON CONFLICT (game_id, language_code) DO NOTHING;
