INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'She Danced in the Wind Like a Holographic Dream Before the World Died', 'A short game poem and interactive fiction about The End. You play the very last flower left on Earth, bringing peace to long dead soil. Explore brutalist ruins to collect memories of a dead world. Maybe your presence can heal what is left.' FROM games WHERE igdb_id = 390004 ON CONFLICT (game_id, language_code) DO NOTHING;
