INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Serenitrove', 'A pixel art digging game where the goal is to dig deeper and uncover more as you progress. Enjoy a relaxed, timer-free experience with no enemies, just pure exploration. Customize your setup, take your time, and excavate as much treasure as you can.' FROM games WHERE igdb_id = 341541 ON CONFLICT (game_id, language_code) DO NOTHING;
