INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrine of Haunts', 'In the summer of 1990, you return to the secluded mountain village of Iwao as your grandfather falls critically ill. The village shrine is said to seal the yokai "Tsuchigumo." As the "Mushi Okuri Festival" nears, its ritual flames may awaken a thousand-year-old curse…' FROM games WHERE igdb_id = 347336 ON CONFLICT (game_id, language_code) DO NOTHING;
