INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outlive 25', 'Old school RTS is back! Outlive 25 is the remastered version of the game originally released in 2000, that will be featuring enhanced graphics and sound, an updated Campaign Editor, Steam multiplayer support, and much more. Get ready for a battle of unprecedented proportions, fought to achieve supremacy—and above all—to ensure humanity’s survival.' FROM games WHERE igdb_id = 357069 ON CONFLICT (game_id, language_code) DO NOTHING;
