INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turnbound', 'Turnbound is an auto battler, where you manage a hero''s inventory to escape a haunted boardgame. Each run is different from the last, with unique upgrades, combos and synergies. Async PvP lets you battle the ghosts of other players at your own pace in this unique new inventory battler. Will your design outlive your ghostly opponents… or join them?' FROM games WHERE igdb_id = 369783 ON CONFLICT (game_id, language_code) DO NOTHING;
