INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NeNeKoNeKo', 'NeNeKoNeKo is a puzzle game where you use three boxes to fit sprawling, oddly-shaped sleeping cats into place. Don''t let the cute looks fool you — under a time limit, you need to quickly figure out the best combinations, making it a surprisingly challenging brain teaser. When time runs out, you get a revival chance with limited moves instead of a time limit, letting you think carefully and discover solutions that seemed impossible. Feel the rush when everything clicks into place!' FROM games WHERE igdb_id = 394761 ON CONFLICT (game_id, language_code) DO NOTHING;
