INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lady Death Demonicron', 'LADY DEATH: DEMONICRON is an all new side-scrolling, sword slicing, magic wielding, 15 level, multiplayer beat-em-up that takes the best aspects of the 1990''s arcade classics - all mixed together with a killer 90''s industrial-metal soundtrack!' FROM games WHERE igdb_id = 310761 ON CONFLICT (game_id, language_code) DO NOTHING;
