INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jury Trial', 'In this law simulation RPG you join a group of innocence lawyers. Set in a fictional country deeply divided by racial profiling, prejudice and social injustice it’s your job to find a jury who’s willing to listen. Study case material, discover new evidence and convince the jury in the court of law.' FROM games WHERE igdb_id = 160157 ON CONFLICT (game_id, language_code) DO NOTHING;
