INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stonemachia', 'Stonemachia is an adventure in which you can fight and explore a world distorted by the Plague of angels, taking on the role of Zefiro, a pawn capable of transforming into other chess pieces. Venture into the lands of Medhelan and prepare to face armies of angels transformed into statues and objects inspired by Italian art, architecture, and folklore! Fight with a variety of abilities and precise timing in a parry-centric game, where the shield can truly change the outcome of every encounter! Discover the various transformations and their unique abilities to experience a Dantesque epic and uncover the secret of the chess pieces...' FROM games WHERE igdb_id = 300028 ON CONFLICT (game_id, language_code) DO NOTHING;
